import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 41 Do you call that a hat?","description":"学习 情态动词的意义与形式，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 41 Do you call that a hat?","description":"学习 情态动词的意义与形式，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 情态动词的意义与形式，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 40 Food and talk","link":"/life/english/new-concept/book-2/unit-02/lesson-040"},"next":{"text":"第二册：实践与进步 · Lesson 42 Not very musical","link":"/life/english/new-concept/book-2/unit-02/lesson-042"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 40 Food and talk","link":"/life/english/new-concept/book-2/unit-02/lesson-040"},"next":{"text":"第二册：实践与进步 · Lesson 42 Not very musical","link":"/life/english/new-concept/book-2/unit-02/lesson-042"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-041.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-041.md"}'),l={name:"life/english/new-concept/book-2/unit-02/lesson-041.md"};function i(s,e,r,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-41-do-you-call-that-a-hat" tabindex="-1">第二册：实践与进步 · Lesson 41 Do you call that a hat? <a class="header-anchor" href="#第二册-实践与进步-·-lesson-41-do-you-call-that-a-hat" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 41 Do you call that a hat?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>买帽子时意见不一致，需要区分必须购买与只是建议试戴；练习情态义务和建议。本课的语言观察是：need not buy 表没有购买必要，不表示禁止购买；must not buy 才是否定许可。对方可以拒绝建议，句子的语气不能混为一谈。完成学习后，请写三句购物建议，区分无需做的事与值得尝试的事。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>hat</td><td>/hæt/</td><td>n.</td><td>帽子</td><td>a woollen hat</td></tr><tr><td>mirror</td><td>/ˈmɪrə/</td><td>n.</td><td>镜子</td><td>look in a mirror</td></tr><tr><td>fashion</td><td>/ˈfæʃən/</td><td>n.</td><td>时尚</td><td>follow fashion</td></tr><tr><td>choose</td><td>/tʃuːz/</td><td>v.</td><td>选择</td><td>choose carefully</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>try something on — 试穿试戴，代词用 try it on</li><li>go with — 与……搭配，描述衣着配色</li></ul><h2 id="语法讲解-情态动词的意义与形式" tabindex="-1">语法讲解：情态动词的意义与形式 <a class="header-anchor" href="#语法讲解-情态动词的意义与形式" aria-label="Permalink to &quot;语法讲解：情态动词的意义与形式&quot;">​</a></h2><p>can、could、may、might、must 等情态动词后接动词原形，否定一般直接加 not，不需要 do。它们可能表示能力、许可、义务或推测，必须根据上下文区分；could 不总是过去时间，也能表示委婉请求或较弱的可能性。must not 表示禁止，do not have to 表示没有必要，二者意义完全不同。判断语气时先问说话人在提出要求还是评价证据。本课应用：need not buy 表没有购买必要，不表示禁止购买；must not buy 才是否定许可。对方可以拒绝建议，句子的语气不能混为一谈。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>You need not buy the hat just because it is fashionable.</p></blockquote><p>你不必仅仅因为这顶帽子时髦就买它。</p><p>need not 在此是情态用法，后接 buy 原形；because 从句说明不应成为唯一理由的因素。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>need not buy 是不必买，不能译成“不准买”；do not need to buy 也是不必买。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对比 need not 与 must not 的重音和意义；读出 fashionable 的重音在首音节。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>You need not buy the hat just because it is fashionable. Try it on in front of the mirror. Choose the one that feels comfortable.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句购物建议，区分无需做的事与值得尝试的事。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：need not 在此是情态用法，后接 buy 原形；because 从句说明不应成为唯一理由的因素。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：need not buy 是不必买，不能译成“不准买”；do not need to buy 也是不必买。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>将“不必买”补全：You do not need ___ buy it.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> 实义动词 need 的否定结构后接 to 不定式。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示范建议优先考虑什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Comfort.</p><p><strong>解析：</strong> 最后一句明确建议选择感觉舒适的款式。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>用代词替换 try the hat on 中的 the hat。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> try it on</p><p><strong>解析：</strong> 代词宾语必须放在 try 与 on 之间。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：情态动词的意义与形式。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-040">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-042">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(l,[["render",i]]);export{p as __pageData,b as default};
